import yaml,glob,os,re
open_ids=[]
for f in glob.glob('items/*.yaml'):
    d=yaml.safe_load(open(f)) or {}
    if d.get('status')=='open': open_ids.append(os.path.basename(f)[:-5])
hits=[]
for i in open_ids:
    p='comments/'+i
    txt=''
    if os.path.isdir(p):
        for c in glob.glob(p+'/*'):
            txt+=open(c,errors='ignore').read()
    elif os.path.exists(p+'.yaml'):
        txt=open(p+'.yaml',errors='ignore').read()
    if re.search(r'archiv(e|ing) this|-- archiving|will archive|now archived|marking (it )?complete|completing this', txt, re.I):
        hits.append(i)
print('open items whose comments declare their own closure:',hits)
