import re,glob,os
ps=sorted(set(glob.glob('AlgebraicJacobian/**/*.lean',recursive=True)) | set(glob.glob('AlgebraicJacobian/*.lean')))
print('files:',len(ps))
def mod(p): return p[:-5].replace('/','.')
files={mod(p) for p in ps}
imports={}
for p in ps:
    imports[mod(p)]=[m.group(1) for m in re.finditer(r'^import\s+(AlgebraicJacobian\S*)',open(p,errors='ignore').read(),re.M)]
root=[m.group(1) for m in re.finditer(r'^import\s+(AlgebraicJacobian\S*)',open('AlgebraicJacobian.lean',errors='ignore').read(),re.M)]
seen=set(); st=list(root)
while st:
    x=st.pop()
    if x in seen: continue
    seen.add(x); st.extend(imports.get(x,[]))
un=sorted(files-seen)
print('UNREACHABLE',len(un))
for u in un: print(' ',u)
"

